    "code": "const firstPromise = new Promise((res, rej) => {\n  setTimeout(res, 500, 'one');\n});\nconst secondPromise = new Promise((res, rej) => {\n  setTimeout(res, 100, 'two');\n});\nPromise.race([firstPromise, secondPromise]).then(res => {\n  console.log(res);\n});",
